"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["16658"],{75577(e){e.exports=JSON.parse('{"id":"FIN-1155","slug":"confirmation-bias","term":"Confirmation Bias","also_known_as":[],"difficulty":"Intermediate","definition":"Confirmation bias is the tendency to seek out, interpret and remember information in ways that support what one already believes, while ignoring or dismissing information that contradicts it.","explanation":["Confirmation bias is one of the most common biases in decision-making. Once someone forms a view, they tend to notice evidence that supports it and overlook evidence against it.","For example, an investor who believes a company\'s shares will rise may focus on positive news and optimistic analyst reports, while dismissing warning signs such as falling sales or rising debt as temporary. This can lead them to hold a losing investment far too long.","Confirmation bias is reinforced by online algorithms and social media, which often show people more of what they already agree with, and by discussing investments mainly with like-minded people.","Ways to reduce it include deliberately seeking out opposing views, writing down the reasons for an investment and what would prove them wrong, reviewing decisions regularly against the original reasoning and asking someone else to challenge the case. Recognising the bias is the first step towards making more balanced decisions."],"note":"","total":1500,"prev":{"slug":"confidential-information-memorandum","term":"Confidential Information Memorandum (CIM)"},"next":{"slug":"consistency-principle","term":"Consistency Principle"}}')}}]);